#!/usr/bin/env node
// Run only in an isolated Node container. Five fresh processes fix TZ before
// Mongoose or Date is loaded. Output is intentionally generated by the owner.
import { createRequire } from 'node:module';
import { readFileSync, writeFileSync, mkdirSync } from 'node:fs';
import { createHash } from 'node:crypto';
import { spawnSync } from 'node:child_process';
import { fileURLToPath } from 'node:url';
import assert from 'node:assert/strict';
import vm from 'node:vm';
const require = createRequire(import.meta.url);
assert.equal(process.versions.node, '24.22.1');
assert.equal(process.versions.v8, '13.6.233.17-node.58');
assert.equal(process.versions.icu, '78.3');
assert.equal(process.versions.tz, '2026e');
const zones = ['UTC','America/New_York','Europe/Berlin','Australia/Lord_Howe','Pacific/Apia'];
const args = process.argv.slice(2);
if (args[0] !== '--child') {
  assert.equal(args.length, 1, 'supply output directory');
  mkdirSync(args[0], {recursive:true});
  for (const zone of zones) {
    const child = spawnSync(process.execPath, [fileURLToPath(import.meta.url), '--child', args[0], zone], {env:{...process.env,TZ:zone},stdio:'inherit'});
    assert.equal(child.status, 0, zone);
  }
  process.exit(0);
}
const [, directory, zone] = args;
const mongoose = require('mongoose');
assert.equal(mongoose.version, '8.24.2');
const instance = new mongoose.Mongoose();
const model = instance.model('DateFixture', new instance.Schema({d:{type:Date,default:123}, requiredDate:{type:Date,required:true}},{_id:false,versionKey:false}));
const source = readFileSync(new URL('../../src/schemas/admin.schema.ts',import.meta.url),'utf8');
const ts = require('typescript');
const compiled = ts.transpileModule(source,{compilerOptions:{module:ts.ModuleKind.CommonJS,target:ts.ScriptTarget.ES2022}}).outputText;
const exports = {};
const localRequire = id => { assert.equal(id,'mongoose'); return {Schema:instance.Schema,model:instance.model.bind(instance),Types:instance.Types}; };
new vm.Script(`(function(exports,require){${compiled}\n})`,{filename:'admin.schema.ts'}).runInThisContext()(exports,localRequire);
const admin = exports.AdminSchema;
const caster = instance.Schema.Types.Date.cast();
const strings = ['', ' ', '\t', '0','1','12','13','49','50','99','100','2000','275760','275761','-271820','-271821','275760.9','-271820.1','1e6','0x43531','0b100','0o77','Infinity','-Infinity','-0','+275761',' 275761 ', '8640000000000000','8640000000000001','-8640000000000000','-8640000000000001','2000-02-30','2024-03-10T02:30:00','2024-11-03T01:30:00','January 4, 2020 10:20:30','Thu, 01 Jan 1970 00:00:00 GMT','+275760-09-13T00:00:00.000Z','-271821-04-20T00:00:00.000Z','not a date'];
const inputs = [null,true,false,...strings,0,-1,1.9,-1.9,275761,8640000000000000,8640000000000001,-8640000000000000,-8640000000000001,[],[0],['2000-01-01'],[null],[[1]], [1,2], [{}], {}, {x:1}].map(v=>({kind:'json',value:v}));
for (const v of ['NaN','Infinity','-Infinity','-0']) inputs.push({kind:'number',value:v},{kind:'boxed',value:v});
for (const v of ['0','1.9','-1.9','8640000000000000','8640000000000001']) inputs.push({kind:'boxed',value:v});
for (const v of ['0','8640000000000000','8640000000000001','-8640000000000001']) inputs.push({kind:'date',value:v});
for (const v of ['9007199254740993','-9007199254740993','1234567890123']) inputs.push({kind:'int64-number',value:v});
function decode(x) { switch(x.kind) {case 'json': return x.value; case 'number': return Number(x.value); case 'boxed': return new Number(Number(x.value)); case 'date': return new Date(Number(x.value)); case 'int64-number': return Number(x.value); default: throw Error(x.kind);} }
function result(v) { try { const d=caster(v); return d===null?{value:null}:{value:d.getTime()}; } catch { return {error:'cast'}; } }
function schema(v, missing=false) { const d=new model(missing?{requiredDate:0}:{d:v,requiredDate:0}); const e=d.validateSync(); return e?{errors:Object.keys(e.errors).sort().map(path=>({path,kind:e.errors[path].name==='CastError'?'cast':e.errors[path].kind}))}:{value:d.d===null?null:d.d.getTime()}; }
function adminResult(v) { const d=new admin({_id:'507f1f77bcf86cd799439011',createdAt:v}); const e=d.validateSync(); return e?{errors:Object.keys(e.errors).sort().map(path=>({path,kind:e.errors[path].name==='CastError'?'cast':e.errors[path].kind}))}:{value:d.createdAt===null?null:d.createdAt.getTime()}; }
const cases=inputs.map(input=>({input,expected:result(decode(input)),schema:schema(decode(input)),admin:adminResult(decode(input))}));
const hash = path=>createHash('sha256').update(readFileSync(require.resolve(path))).digest('hex');
const metadata={node:process.version,versions:process.versions,mongoose:mongoose.version,zone,hashes:{oracle:createHash('sha256').update(readFileSync(fileURLToPath(import.meta.url))).digest('hex'),adminSource:createHash('sha256').update(source).digest('hex'),caster:hash('mongoose/lib/cast/date'),schemaDate:hash('mongoose/lib/schema/date'),schemaType:hash('mongoose/lib/schemaType'),castError:hash('mongoose/lib/error/cast')}};
writeFileSync(`${directory}/${zone.replaceAll('/','_')}.json`,JSON.stringify({metadata,cases,missing:schema(null,true)},null,2)+'\n');
console.log(JSON.stringify({zone,cases:cases.length,checksPerCase:3,mongoose:mongoose.version,hashes:metadata.hashes}));
